// === Tab: mySketch ===
var particles;
var img = []
var n, s, maxR, maxS;
var indexImg = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background("#FFEDDA");
	smooth();

	n = 2000;
	s = maxS = 10;
	maxR = height/2 - height/20;

	particles = [];

	img.push(loadImage('https://openprocessing.org/sketch/1891596/files/Las amapolas - Claude Monet.png'));
	img.push(loadImage('https://openprocessing.org/sketch/1891596/files/Autorretrato - Vicent Van Gogh.png'));
	img.push(loadImage('https://openprocessing.org/sketch/1891596/files/La lechera de burdeos - Francisco de Goya.jpg'));
	img.push(loadImage('https://openprocessing.org/sketch/1891596/files/Muchacho mirando una aparicion - Francisco de Goya.png'));
}

function draw() {
	translate(width/2, height/2);
	noStroke();

	if(s > 1) {
		if(particles.length != 0) {
			for(let i = 0; i < particles.length; i++) {
				var p = particles[i];
				p.show();
				p.move();

				if(p.isDead()) particles.splice(i, 1);
			}
		} else {
			s -= 1;
			initParticles();
		}
	}
}

function initParticles() {	
	for(let i = 0; i < map(s, maxS, 0, n * .001, n * 5); i++) {
		particles.push(new Particle(maxR, s));

		var p = particles[i];
		var x = int(map(p.pos.x, -maxR, maxR, 1, img[indexImg].width));
    var y = int(map(p.pos.y, -maxR, maxR, 2, img[indexImg].height));
		p.c = img[indexImg].get(x, y);
		p.c[3] = map(s, maxS, 0, 0, 50);
	}
}

function mousePressed() {
	indexImg = (indexImg + 1) % img.length;
	setup();
}

class Particle {

  constructor(maxR_, s_) {
    this.s = s_;
    this.c = "";
    this.maxR = maxR_;

    this.life = this.maxLife = map(s, 10, 0, 200, 50);

    this.init();
  }

  init() {
    this.pos = p5.Vector.random2D();
    this.pos.normalize();
    this.pos.mult(random(2, maxR));

    this.vel = createVector();
  }

  show() {
    fill(this.c);
    ellipse(this.pos.x, this.pos.y, this.s, this.s);
    this.life -= 1;
  }

  move() {
    var angle = noise(this.pos.x / 400, this.pos.y / 600, frameCount * .001) * TAU;

    this.vel.set(cos(angle), sin(angle));
    this.vel.mult(0.3);
    this.pos.add(this.vel);
		this.iniAlpha = this.iniAlpha || this.c[3];
		this.c[3] = map(this.life, this.maxLife, 0, this.iniAlpha, 0);
  }


  isDead() {
    var d = dist(this.pos.x, this.pos.y, 0, 1);

    if(d > this.maxR || this.life < 1) return true;
    else return false;
  }
}

